.setting-item[data-id="light-theme-color-swatches"] .setting-item-control,
.setting-item[data-id="dark-theme-color-swatches"] .setting-item-control {
  display: flex;
  align-items: center;
  gap: var(--size-4-2);
  flex-wrap: wrap;
}
.setting-item[data-id="light-theme-color-swatches"] .setting-item-control::before {
  content: "";
  display: block;
  width: 130px;
  height: 20px;
  flex-shrink: 0;
  border-radius: var(--radius-s, 4px);
  box-shadow: inset 0 0 0 1px var(--background-modifier-border);
  background: linear-gradient(to right,
    var(--lt-color-red) 0%, var(--lt-color-red) 11.11%,
    var(--lt-color-orange) 11.11%, var(--lt-color-orange) 22.22%,
    var(--lt-color-yellow) 22.22%, var(--lt-color-yellow) 33.33%,
    var(--lt-color-green) 33.33%, var(--lt-color-green) 44.44%,
    var(--lt-color-cyan) 44.44%, var(--lt-color-cyan) 55.56%,
    var(--lt-color-blue) 55.56%, var(--lt-color-blue) 66.67%,
    var(--lt-color-purple) 66.67%, var(--lt-color-purple) 77.78%,
    var(--lt-color-pink) 77.78%, var(--lt-color-pink) 88.89%,
    var(--lt-color-brown) 88.89%, var(--lt-color-brown) 100%
  );
}
.setting-item[data-id="dark-theme-color-swatches"] .setting-item-control::before {
  content: "";
  display: block;
  width: 130px;
  height: 20px;
  flex-shrink: 0;
  border-radius: var(--radius-s, 4px);
  box-shadow: inset 0 0 0 1px var(--background-modifier-border);
  background: linear-gradient(to right,
    var(--dt-color-red) 0%, var(--dt-color-red) 11.11%,
    var(--dt-color-orange) 11.11%, var(--dt-color-orange) 22.22%,
    var(--dt-color-yellow) 22.22%, var(--dt-color-yellow) 33.33%,
    var(--dt-color-green) 33.33%, var(--dt-color-green) 44.44%,
    var(--dt-color-cyan) 44.44%, var(--dt-color-cyan) 55.56%,
    var(--dt-color-blue) 55.56%, var(--dt-color-blue) 66.67%,
    var(--dt-color-purple) 66.67%, var(--dt-color-purple) 77.78%,
    var(--dt-color-pink) 77.78%, var(--dt-color-pink) 88.89%,
    var(--dt-color-brown) 88.89%, var(--dt-color-brown) 100%
  );
}
