/* ::: Accent Fallbacks ::: */

.theme-light {
  --accent: 26, 72%, 35%;
}
.theme-dark {
  --accent: 39, 88%, 61%;
}

/* ::: Accent ::: */

.theme-dark:not(.obsidian),
.theme-light:not(.obsidian) {
    --interactive-accent-hsl: var(--accent);
    --color-accent-hsl: var(--accent);

    --color-accent: hsl(var(--accent));
    --color-accent-1: color-mix(in srgb, hsl(var(--accent)), white 15%);
    --color-accent-2: color-mix(in srgb, hsl(var(--accent)), white 30%);

    --interactive-accent: var(--color-accent);
    --interactive-accent-hover: var(--color-accent-1);
}

.theme-dark:not(.obsidian),
.theme-light:not(.obsidian) {
  --bb-input-bg: var(--bb-tiptips-bg);
  --bb-input-hover-bg: var(--bb-tiptips-hover-bg);

  --background-primary: var(--bb-editor-bg);
  --background-primary-alt: var(--bb-elements-bg);
  --background-secondary: var(--bb-workspace-bg);
  --background-secondary-alt: var(--bb-workspace-bg);

  --tab-background: var(--bb-editor-bg);
  --tab-background-hover: var(--bb-elements-bg);
  --tab-background-active: var(--bb-editor-bg);

  --interactive-normal: var(--bb-tiptips-bg);
  --interactive-hover: var(--bb-tiptips-hover-bg);
  --background-modifier-form-field: var(--bb-input-bg);
  --background-modifier-form-field-hover: var(--bb-input-hover-bg);
  --background-modifier-border: var(--bb-border-color);
  --background-modifier-border-hover: var(--bb-border-hover-color);
  --background-modifier-border-focus: var(--bb-border-focused-color);

  --text-normal: var(--txt-n);
  --text-muted: var(--txt-m);
  --text-faint: var(--text-f);
  
  --text-success: var(--color-green);
  --text-warning: var(--color-red);
  --text-error: var(--color-red);
  --text-accent: var(--color-accent);
  --text-accent-hover: var(--color-accent-2);

  --scrollbar-bg: var(--bb-tiptips-bg);
  --scrollbar-thumb-bg: var(--bb-tiptips-hover-bg);
  --scrollbar-active-thumb-bg: var(--bb-tiptips-bg);
}

.theme-dark, .theme-light {
  --accent-red: var(--color-red);
  --accent-orange: var(--color-orange);
  --accent-yellow: var(--color-yellow);
  --accent-green: var(--color-green);
  --accent-cyan: var(--color-cyan);
  --accent-blue: var(--color-blue);
  --accent-purple: var(--color-purple);
  --accent-pink: var(--color-pink);
  --accent-brown: var(--color-brown);
  --accent-gray: var(--text-normal);
}

/* background mapping (moved from snippets/tabs.css) */
:root {
  --background-primary: var(--bb-editor-bg);
  --background-primary-alt: var(--bb-elements-bg);
  --background-secondary: var(--bb-workspace-bg);
  --background-secondary-alt: var(--bb-workspace-bg);
}
