/* ::: Folder Styling ::: */

body {
  --folder-frame-gap: 8px;
  --file-frame-gap: 4px;
  --folder-padding-horizontal: 14px;
  --folder-padding-vertical: 5px;
  --folder-bg-opacity: 100;
  --folder-border-opacity: 100;
  --folder-border-thickness: 2px;
  --file-title-margin: 0px;
  --nav-indentation-guide-width: 2px;
  --folder-title-margin: 34px;
  --folder-radius: var(--radius-m);
}

/* :: Frame */
body.folder-border.folder-target-frame .nav-folder {
  border: var(--folder-border-thickness) solid var(--folder-border-color);
}

/* :: Frame + Header */
body.folder-border.folder-target-frame-header .nav-folder {
  border: var(--folder-border-thickness) solid var(--folder-border-color);
  overflow: clip;
  overflow-clip-margin: var(--folder-border-thickness);
}

body.folder-border.folder-target-frame-header .nav-folder:not(.is-collapsed) > .nav-folder-title:not(.is-collapsed) {
  border-bottom: var(--folder-border-thickness) solid var(--folder-border-color);
  border-bottom-left-radius: 0;
  border-bottom-right-radius: 0;
}

/* :: Header */
body.folder-target-header .nav-folder {
  background-color: transparent;
  overflow: clip;
  overflow-clip-margin: var(--folder-border-thickness);
}

body.folder-target-header .nav-folder-title {
  background-color: color-mix(in oklch, var(--folder-bg) calc(var(--folder-bg-opacity) * 1%), transparent);
  border-radius: var(--folder-radius);
}

body.folder-border.folder-target-header .nav-folder-title {
  border: var(--folder-border-thickness) solid var(--folder-border-color);
}

/* :: Title Text */
body.folder-target-text .nav-folder-title-content {
  background-color: color-mix(in oklch, var(--folder-bg) calc(var(--folder-bg-opacity) * 1%), transparent);
  border-radius: var(--folder-radius);
}

body.folder-border.folder-target-text .nav-folder-title-content {
  border: var(--folder-border-thickness) solid var(--folder-border-color);
}

body.folder-target-text .nav-folder {
  background-color: transparent;
}

/* :: Title + Icon */
/*
body.folder-border.folder-target-text-icon .nav-folder-title-content {
  border: var(--folder-border-thickness) solid var(--folder-border-color);
  border-radius: var(--folder-radius);
}

body.folder-border.folder-target-text-icon .nav-folder-title .collapse-icon {
  border: var(--folder-border-thickness) solid var(--folder-border-color);
  border-radius: var(--folder-radius);
}
*/

/* :: Frame Gap + Padding */
.nav-folder {
  margin-block-end: var(--folder-frame-gap);
  border-radius: var(--folder-radius);
}

.nav-folder-title {
  align-items: center;
  column-gap: var(--size-4-1);
  padding-inline-end: var(--folder-padding-horizontal);
}

.nav-folder-title > .collapse-icon {
  flex: none;
  margin-inline-start: var(--folder-padding-horizontal);
}

.nav-folder-title-content {
  padding-block: var(--folder-padding-vertical);
}

.nav-folder-children {
  padding-inline: var(--folder-padding-horizontal);
  padding-block: var(--folder-padding-vertical);
}

/* :: Corner Shape */
body.folder-corner-round :is(.nav-folder, .nav-file, .nav-folder-title, .nav-folder-title-content) {
  corner-shape: round;
}

body.folder-corner-squircle :is(.nav-folder, .nav-file, .nav-folder-title, .nav-folder-title-content) {
  corner-shape: squircle;
}

body.folder-corner-scoop :is(.nav-folder, .nav-file, .nav-folder-title, .nav-folder-title-content) {
  corner-shape: scoop;
}

body.folder-corner-bevel :is(.nav-folder, .nav-file, .nav-folder-title, .nav-folder-title-content) {
  corner-shape: bevel;
}

body.folder-corner-notch :is(.nav-folder, .nav-file, .nav-folder-title, .nav-folder-title-content) {
  corner-shape: notch;
}

body.folder-corner-square :is(.nav-folder, .nav-file, .nav-folder-title, .nav-folder-title-content) {
  corner-shape: square;
}

/* :: File Corner Overrides */
body.file-corner-round .nav-files-container .nav-file {
  corner-shape: round;
}

body.file-corner-squircle .nav-files-container .nav-file {
  corner-shape: squircle;
}

body.file-corner-scoop .nav-files-container .nav-file {
  corner-shape: scoop;
}

body.file-corner-bevel .nav-files-container .nav-file {
  corner-shape: bevel;
}

body.file-corner-notch .nav-files-container .nav-file {
  corner-shape: notch;
}

body.file-corner-square .nav-files-container .nav-file {
  corner-shape: square;
}

/* :: Title Alignment */
body.folder-title-align-left .nav-folder-title > .nav-folder-title-content {
  flex: 1 1 auto;
  text-align: left;
  /* margin-inline-start: calc(var(--folder-padding-horizontal) + var(--size-4-6) + var(--size-4-1)); */
  margin-inline-start: var(--folder-title-margin);
}

body.folder-title-align-center .nav-folder-title > .nav-folder-title-content {
  flex: 1 1 auto;
  text-align: center;
  margin-inline: var(--folder-title-margin);
}

body.folder-title-align-right .nav-folder-title > .nav-folder-title-content {
  flex: 1 1 auto;
  text-align: right;
  margin-inline-end: var(--folder-title-margin);
}

/* :: Text Target + Left Align */
body.folder-target-text.folder-title-align-left .nav-folder-title > .nav-folder-title-content {
  flex: none;
  padding: var(--size-4-1) var(--size-2-3);
}

/* :: File Frame */
.nav-file {
  margin-block-end: var(--file-frame-gap);
  padding: var(--size-2-1) var(--size-2-3);
  border-radius: var(--file-radius, var(--folder-radius));
}

.nav-file-title {
  align-items: center;
  column-gap: var(--size-4-1);
}

/* :: File Active Frame */
body .nav-files-container .nav-file .nav-file-title:is(.is-active, :hover) {
  background-color: transparent;
}

.nav-file:has(> .nav-file-title:is(.is-active, :hover)) {
  background-color: var(--nav-item-background-active);
}

/* :: Folder Hover */
body .nav-files-container .nav-folder .nav-folder-title:hover {
  background-color: transparent;
}

.nav-folder:has(> .nav-folder-title:hover) {
  background-color: var(--nav-item-background-active);
}

/* :: Hide Icons */
body.hide-folder-icons .nav-folder-title > .collapse-icon {
  display: none;
}

body.hide-file-icons .nav-file-title > .tree-item-icon {
  display: none;
}

/* :: File Title Alignment */
body.file-title-align-left .nav-file-title > .nav-file-title-content {
  flex: 1 1 auto;
  text-align: left;
  margin-inline-start: var(--file-title-margin);
}

body.file-title-align-center .nav-file-title > .nav-file-title-content {
  flex: 1 1 auto;
  text-align: center;
  margin-inline: var(--file-title-margin);
}

body.file-title-align-right .nav-file-title > .nav-file-title-content {
  flex: 1 1 auto;
  text-align: right;
  margin-inline-end: var(--file-title-margin);
}

/* :: Folder Background */
.nav-folder {
  --folder-bg: var(--interactive-hover);
  --folder-border-color: color-mix(in oklch, var(--folder-bg) calc(var(--folder-border-opacity) * 1%), transparent);
  background-color: color-mix(in oklch, var(--folder-bg) calc(var(--folder-bg-opacity) * 1%), transparent);
}

body.folder-bg-interactive .nav-folder {
  --folder-bg: var(--interactive-normal);
