/* ::: SLIDING PANELS ::: */

/* Tokens */

body:not(.is-mobile) {
  --soh-width: 300px;
  --soh-edge: 8px;
  --soh-delay: 120ms;
  --soh-duration: 180ms;
  --soh-inset: 0px;
  --soh-layer: 11;
}

/* containing block -- the panels are out of flow */
body:not(.is-mobile):is(.soh-left-edge, .soh-left-ribbon, .soh-left-fade, .soh-right-edge, .soh-right-fade) .workspace {
  position: relative;
}

/* Left sidebar */

/* out of flow -- parking it costs no layout width */
body:not(.is-mobile):is(.soh-left-edge, .soh-left-fade, .soh-left-ribbon.show-ribbon) .workspace-split.mod-left-split {
  position: absolute;
  inset-block: 0;
  inset-inline-start: var(--soh-inset);
  flex: none;
  width: var(--soh-width);
  min-width: 0;
  margin: 0;
  z-index: var(--soh-layer);
}

/* header must paint above the root tabs it overlaps */
body:not(.is-mobile):is(.soh-left-edge, .soh-left-fade, .soh-left-ribbon.show-ribbon) .workspace-split.mod-left-split .workspace-tab-header-container {
  position: relative;
  z-index: 2;
}

/* docked closed -- nothing to reveal otherwise */
body:is(.ribbon-off-sidebar-show):not(.is-mobile):is(.soh-left-edge, .soh-left-fade, .soh-left-ribbon.show-ribbon) .workspace-split.mod-left-split.is-sidedock-collapsed {
  display: flex !important;
  width: var(--soh-width) !important;
}

body:not(.is-mobile):is(.soh-left-edge, .soh-left-fade, .soh-left-ribbon.show-ribbon) .workspace-split.mod-left-split .workspace-tabs {
  visibility: visible;
}

/* past the ribbon -- it owns the window edge whenever it is shown, and sits above the panel */
body:not(.is-mobile):is(.soh-left-edge, .soh-left-ribbon, .soh-left-fade).show-ribbon .workspace-split.mod-left-split {
  --soh-inset: var(--ribbon-width, 0px);
}

/* ribbon stays above the panel */
body:not(.is-mobile):is(.soh-left-edge, .soh-left-ribbon, .soh-left-fade).show-ribbon .workspace-ribbon:is(.mod-left, .mod-primary) {
  z-index: calc(var(--soh-layer) + 1);
}

/* ribbon mode -- parked past the inset too, else the last --soh-inset sits on the ribbon */
body:not(.is-mobile).soh-left-ribbon.show-ribbon .workspace-split.mod-left-split {
  transform: translateX(calc(-1 * (100% + var(--soh-inset))));
  transition: transform var(--soh-duration) ease;
}

/* edge mode -- the sliver ends past the inset, so it is never buried under the ribbon */
body:not(.is-mobile).soh-left-edge .workspace-split.mod-left-split {
  transform: translateX(calc(var(--soh-edge) - 100%));
  transition: transform var(--soh-duration) ease;
}

/* reveal -- the sliver stays covered, so hover never drops out mid-open */
body:not(.is-mobile).soh-left-edge .workspace-split.mod-left-split:hover,
body:not(.is-mobile).soh-left-ribbon.show-ribbon .workspace-split.mod-left-split:hover,
body:not(.is-mobile).soh-left-ribbon.show-ribbon .workspace-ribbon:is(.mod-left, .mod-primary):hover ~ .workspace-split:is(.mod-left-split, .mod-primary-split) {
  transform: none;
  transition: transform var(--soh-duration) ease-out var(--soh-delay);
}

/* fade mode -- parked in place, no slide, just transparent */
body:not(.is-mobile).soh-left-fade .workspace-split.mod-left-split {
  opacity: 0;
  transform: none;
  transition: opacity var(--soh-duration) ease;
}

/* reveal -- hovering the panel itself or the ribbon */
body:not(.is-mobile).soh-left-fade .workspace-split.mod-left-split:hover,
body:not(.is-mobile).soh-left-fade.show-ribbon .workspace-ribbon:is(.mod-left, .mod-primary):hover ~ .workspace-split:is(.mod-left-split, .mod-primary-split) {
  opacity: 1;
  transition: opacity var(--soh-duration) ease-out var(--soh-delay);
}

/* Right sidebar */

/* out of flow -- parking it costs no layout width */
body:not(.is-mobile):is(.soh-right-edge, .soh-right-fade) .workspace-split.mod-right-split {
  position: absolute;
  inset-block: 0;
  inset-inline-end: 0;
  flex: none;
  width: var(--soh-width);
  min-width: 0;
  margin: 0;
  z-index: var(--soh-layer);
}

/* header must paint above the root tabs it overlaps */
body:not(.is-mobile):is(.soh-right-edge, .soh-right-fade) .workspace-split.mod-right-split .workspace-tab-header-container {
  position: relative;
  z-index: 2;
}

/* docked closed -- nothing to reveal otherwise */
body:not(.is-mobile):is(.soh-right-edge, .soh-right-fade) .workspace-split.mod-right-split.is-sidedock-collapsed {
  display: flex !important;
  width: var(--soh-width) !important;
}

body:not(.is-mobile):is(.soh-right-edge, .soh-right-fade) .workspace-split.mod-right-split .workspace-tabs {
  visibility: visible;
}

/* edge mode -- no right ribbon, so the window edge itself is the trigger */
body:not(.is-mobile).soh-right-edge .workspace-split.mod-right-split {
  transform: translateX(calc(100% - var(--soh-edge)));
  transition: transform var(--soh-duration) ease;
}

/* reveal -- the sliver stays covered, so hover never drops out mid-open */
body:not(.is-mobile).soh-right-edge .workspace-split.mod-right-split:hover {
  transform: none;
  transition: transform var(--soh-duration) ease-out var(--soh-delay);
}

/* fade mode -- parked in place, no slide, just transparent */
body:not(.is-mobile).soh-right-fade .workspace-split.mod-right-split {
  opacity: 0;
  transform: none;
  transition: opacity var(--soh-duration) ease;
}

/* reveal -- hovering the panel itself */
body:not(.is-mobile).soh-right-fade .workspace-split.mod-right-split:hover {
  opacity: 1;
  transition: opacity var(--soh-duration) ease-out var(--soh-delay);
}

/* Frameless windows */

/* overlays the title bar, so keep it out of the drag region */
body:not(.is-mobile):is(.soh-left-edge, .soh-left-fade, .soh-left-ribbon.show-ribbon) .workspace-split.mod-left-split div:is(.workspace-tab-header-container, .workspace-tab-header-container-inner),
body:not(.is-mobile):is(.soh-right-edge, .soh-right-fade) .workspace-split.mod-right-split div:is(.workspace-tab-header-container, .workspace-tab-header-container-inner) {
  -webkit-app-region: no-drag;
}
