/* ::: Style Settings Headings ::: */

body {
  --bb-settings-radius: var(--setting-items-radius);
  --bb-heading-card-bg: var(--background-primary-alt);
  --bb-heading-body-bg: var(--background-primary-alt);
}

/* :: Card Shape */
.style-settings-heading[data-level][data-id],
.style-settings-heading[data-level][data-id] + .style-settings-container,
.style-settings-container > .setting-item:not(.style-settings-heading) {
  corner-shape: var(--bb-corner-shape);
}

.style-settings-heading[data-id] .style-settings-collapse-indicator {
  display: none;
}

.style-settings-heading[data-level][data-id] {
  border: none;
  padding: var(--size-4-2) 0;
  margin-block-start: var(--size-4-2);
  margin-block-end: 0;
}

.style-settings-heading[data-level][data-id] + .style-settings-container {
  padding-inline-start: 0;
  --bb-container-bottom: var(--border-width) solid var(--background-modifier-border);
  --bb-item-divider: 2px solid var(--background-modifier-border-hover);
}

/* insets */

.style-settings-heading[data-level][data-id],
.style-settings-heading[data-level][data-id] + .style-settings-container {
  margin-inline-start: 10px;
  margin-inline-end: 10px;
  border: var(--border-width) solid var(--background-modifier-border);
}

/* level Numbers */
/* 
.style-settings-heading[data-level="0"] + .style-settings-container
  .style-settings-heading[data-level="1"]
  > .setting-item-info
  > .setting-item-name::before {
  content: "1) ";
}

.style-settings-heading[data-level="1"] + .style-settings-container
  .style-settings-heading[data-level="2"]
  > .setting-item-info
  > .setting-item-name::before {
  content: "2) ";
}

:is(
  .style-settings-heading[data-level="1"],
  .style-settings-heading[data-level="2"]
) + .style-settings-container
  .style-settings-heading[data-level="3"]
  > .setting-item-info
  > .setting-item-name::before {
  content: "3) ";
}

:is(
  .style-settings-heading[data-level="1"],
  .style-settings-heading[data-level="2"],
  .style-settings-heading[data-level="3"]
) + .style-settings-container
  .style-settings-heading[data-level="4"]
  > .setting-item-info
  > .setting-item-name::before {
  content: "4) ";
} */

/* expanded group */

.style-settings-heading[data-id]:not(.is-collapsed) .setting-item-name {
  color: var(--color-accent-2);
}

.style-settings-heading[data-id]:not(.is-collapsed)::before {
  background-color: var(--color-accent-2);
}

.style-settings-heading[data-level][data-id]:not(.is-collapsed) {
  background-color: var(--bb-heading-card-bg);
  border: var(--border-width) solid var(--background-modifier-border);
  border-bottom-width: 2px;
  border-top-left-radius: var(--bb-settings-radius);
  border-top-right-radius: var(--bb-settings-radius);
  border-bottom-left-radius: 0;
  border-bottom-right-radius: 0;
  padding: var(--size-4-2) var(--size-4-4);
  margin-block-end: 0;
}

.style-settings-heading[data-level][data-id]:not(.is-collapsed)
  + .style-settings-container {
  background-color: var(--bb-heading-body-bg);
  border: var(--border-width) solid var(--background-modifier-border);
  border-bottom-left-radius: var(--bb-settings-radius);
  border-bottom-right-radius: var(--bb-settings-radius);
  padding-block-end: 0;
  margin-block-end: var(--size-4-2);
}

.style-settings-heading[data-level][data-id]:not(.is-collapsed)
  + .style-settings-container
  > .style-settings-heading:first-child {
  margin-block-start: var(--size-4-2);
}

/* :: Nested Heading Cards */

:where(.style-settings-heading[data-level]:not([data-level="0"]))[data-id] {
  --bb-heading-card-bg: var(--interactive-normal);
}

/* :: Level Card Colors */

:where(.style-settings-heading[data-level]:not([data-level="0"]))[data-id]
  + .style-settings-container {
  --bb-heading-body-bg: var(--interactive-normal);
}

.style-settings-heading[data-level="1"][data-id] {
  --bb-heading-card-bg: var(--interactive-normal);
}

.style-settings-heading[data-level="1"][data-id] + .style-settings-container {
  --bb-heading-body-bg: var(--interactive-normal);
  --bb-container-bottom: 2px solid var(--background-modifier-border-hover);
  --bb-item-divider: 2px solid var(--background-modifier-border-hover);
}

.style-settings-heading[data-level="2"][data-id] {
  --bb-heading-card-bg: var(--background-secondary);
}

.style-settings-heading[data-level="2"][data-id] + .style-settings-container {
  --bb-heading-body-bg: var(--background-primary-alt);
  padding-bottom: 2px !important;
}

/* Dark & Light Theme */

.style-settings-heading[data-level][data-id="h-dark-theme"] + .style-settings-container,
.style-settings-heading[data-level][data-id="h-light-theme"] + .style-settings-container {
  --bb-heading-body-bg: var(--interactive-normal);
  --bb-container-bottom: 2px solid var(--background-modifier-border-hover);
  --bb-item-divider: 2px solid var(--background-modifier-border-hover);
}

/* Markdown Elements */

.style-settings-heading[data-level][data-id="h-markdown"]:not(.is-collapsed)
  + .style-settings-container {
  border-bottom-left-radius: calc(var(--bb-settings-radius) + 4px);
  border-bottom-right-radius: calc(var(--bb-settings-radius) + 4px);
}

/* :: Section Divider */
.style-settings-heading[data-id="h-sec-desktop"],
.style-settings-heading[data-id="h-hello"] {
  position: relative;
  margin-top: 25px !important;
}

/* divider */
.style-settings-heading[data-id="h-sec-desktop"]::after,
.style-settings-heading[data-id="h-hello"]::after {
  content: "";
  position: absolute;
  inset-inline: 0;
  top: -15px;
  height: 2px;
  transform: translateX(calc(100% - 97%));
  width: 95%;
  background: var(--background-modifier-border-hover);
}

/* :: Row Dividers */
.style-settings-heading[data-level][data-id]:not(.is-collapsed)
  + .style-settings-container {
  border-bottom: var(
    --bb-container-bottom,
    var(--border-width) solid var(--background-modifier-border)
  );
}

.style-settings-container
  > .setting-item:not(.style-settings-heading)
  ~ .setting-item:not(.style-settings-heading) {
  border-top: var(--bb-item-divider, none);
  border-top-left-radius: 0;
  border-top-right-radius: 0;
}

/* :: Collapsed Card */

.style-settings-heading[data-level][data-id].is-collapsed {
  background-color: var(--bb-heading-card-bg);
  border: var(--border-width) solid var(--background-modifier-border);
  border-radius: var(--bb-settings-radius);
  padding: var(--size-4-2) var(--size-4-4);
  margin-block-end: var(--size-4-2);
}

/* :: Setting Items */

.setting-item {
  margin-bottom: 0;
  corner-shape: var(--bb-corner-shape);
}

.setting-group .setting-group-search {
  corner-shape: var(--bb-corner-shape);
}

.style-settings-container > .setting-item:not(.style-settings-heading) {
  background-color: var(--bb-heading-body-bg);
  border-radius: var(--bb-settings-radius);
  border-bottom-left-radius: 0;
  border-bottom-right-radius: 0;
}

.style-settings-container
  > .setting-item:not(.style-settings-heading):last-child {
  border-bottom-left-radius: var(--bb-settings-radius);
  border-bottom-right-radius: var(--bb-settings-radius);
}

/* ss search row  */
.style-settings-container > .setting-item:not([data-id]),
.vertical-tab-content > .setting-item:first-child:not([data-id]),
.view-content > .setting-item:first-child:not([data-id]) {
  background-color: transparent;
}

/* ::: Heading Icons ::: */

.style-settings-heading[data-id]::before {
  width: var(--icon-s);
  height: var(--icon-s);
  flex: 0 0 auto;
  align-self: center;
  margin-inline-end: var(--size-4-3);
  background-color: currentColor;
  -webkit-mask: var(--bb-heading-icon, none) no-repeat center / contain;
  mask: var(--bb-heading-icon, none) no-repeat center / contain;
}

