.style-settings-heading[data-level][data-id]:not(.is-collapsed) {
  border-bottom: 2px solid var(--background-modifier-border-hover);
}

/* :: Level 4 Card Colors */

.style-settings-heading[data-level="4"][data-id] {
  --bb-heading-card-bg: var(--background-secondary);
}

.style-settings-heading[data-level="4"][data-id] + .style-settings-container {
  --bb-heading-body-bg: var(--background-primary-alt);
}


.setting-item-info {
  flex: 1 1 100%;
}
.setting-item {
  align-items: center;
}

/* select coloring */

.dropdown option[value^="heading-"] {
    background-color: hsla(var(--interactive-accent-hsl), 0.75) !important;
    color: var(--text-normal) !important;
    font-weight: 600;
    text-align: center;
    pointer-events: none;
    cursor: default;
    font-size: 0.9em;
    letter-spacing: 0.05em;
    padding: 10px 0;
}

/* Red heading */
.dropdown option[value^="heading-red"] {
    background-color: rgba(var(--color-red-rgb), 0.75) !important;
}

/* Orange heading */
.dropdown option[value^="heading-warm"],
.dropdown option[value^="heading-orange"] {
    background-color: rgba(var(--color-orange-rgb), 0.75) !important;
}

/* Yellow heading */
.dropdown option[value^="heading-yellow"] {
    background-color: rgba(var(--color-yellow-rgb), 0.75) !important;
}

/* Green heading */
.dropdown option[value^="heading-green"] {
    background-color: rgba(var(--color-green-rgb), 0.75) !important;
}

/* Blue heading */
.dropdown option[value^="heading-blue"] {
    background-color: rgba(var(--color-blue-rgb), 0.75) !important;
}

/* Purple heading */
.dropdown option[value^="heading-purple"] {
    background-color: rgba(var(--color-purple-rgb), 0.75) !important;
}

/* Pink heading */
.dropdown option[value^="heading-pink"] {
    background-color: rgba(var(--color-pink-rgb), 0.75) !important;
}




/* :: Trigger */
body .pickr .pcr-button,
body .pickr .pcr-button::before,
body .pickr .pcr-button::after {
    border-radius: var(--button-radius);
    corner-shape: var(--bb-corner-shape);
}

/* sized on the button alone so the checkerboard and colour layers keep filling it */
body .pickr .pcr-button {
    box-shadow: none;
    height: var(--size-4-9);
    min-width: var(--size-4-9);
    outline: 2px solid var(--bb-border-focused-color);
}

/* :: Bordered variant */
.button-bordered .pickr button {
    background: none;
    border: none;
    box-shadow: none;
}

/* :: Popup */
body .pcr-app {
    background: var(--background-primary);
    border: var(--border-width) solid var(--background-modifier-border);
    border-radius: calc(var(--button-radius) * 1.4);
    corner-shape: var(--bb-corner-shape);
    min-width: 250px;
}

/* :: Colour square */
body .pcr-palette,
body .pcr-palette::before,
body .pcr-palette::after {
    border-radius: calc(var(--button-radius) * 1.4);
    border-bottom-left-radius: 0;
    border-bottom-right-radius: 0;
    corner-shape: var(--bb-corner-shape);
}

/* :: Hue slider */
body .pcr-color-chooser {
    transform: translateY(10px);
}

/* :: Hex field */
body .pcr-app .pcr-interaction .pcr-result {
    background: var(--bb-tiptips-bg);
    border-radius: calc(var(--button-radius) * 0.8);
    corner-shape: var(--bb-corner-shape);
    font-family: var(--font-monospace);
    min-width: 110px;
}

/* :: Inactive mode */
body .pcr-app .pcr-interaction .pcr-type {
    background: var(--bb-tiptips-hover-bg);
    color: var(--text-faint);
}

/* :: Active mode */
body .pcr-app .pcr-interaction .pcr-type.active,
body .pcr-app .pcr-interaction .pcr-save {
    background: var(--color-accent);
    border: var(--border-width) solid var(--bb-border-focused-color);
}

/* :: Cancel */
body .pcr-app .pcr-interaction .pcr-cancel {
    background: color-mix(in oklch, var(--color-red) 50%, transparent);
}

/* :: Action row */
body .pcr-type,
body .pcr-save,
body .pcr-cancel {
    order: -1;
}

/* :: Swatches */
body .pcr-app .pcr-swatches > button,
body .pcr-app .pcr-swatches > button::before,
body .pcr-app .pcr-swatches > button::after {
    border-radius: calc(var(--button-radius) * 0.8);
    corner-shape: var(--bb-corner-shape);
}

/* :: Focus rings */
body .pcr-app .pcr-interaction .pcr-result:focus,
body .pcr-app .pcr-interaction .pcr-type:focus {
    box-shadow: none;
    outline: 2px solid var(--color-accent-2);
}

/* ::: Themed Color Rows ::: */

/* pair */
.themed-color-wrapper {
    display: flex;
    flex-direction: row;
    gap: var(--size-4-2);
    min-height: 100%;
}

/* stacked */
body:is(.is-mobile):not(.is-tablet) .themed-color-wrapper {
    flex-direction: column;
}

/* halves */
.themed-color-wrapper,
.themed-color-wrapper .theme-light,
.themed-color-wrapper .theme-dark {
    border-radius: var(--touch-radius-s);
    corner-shape: var(--bb-corner-shape);
}

/* inner gap */
.themed-color-wrapper .theme-light,
.themed-color-wrapper .theme-dark {
    gap: var(--size-2-3);
}

/* reset */
body .themed-color-wrapper .pickr-reset > button {
    margin: var(--size-4-1);
    padding: var(--size-2-3) var(--size-4-2);
}

/* row spacing */
body .themed-color-wrapper > div + div {
    margin-top: 0;
}

/* labels */
.themed-color-wrapper .theme-light::before {
    content: "LIGHT";
    margin-right: var(--size-2-3);
}
.themed-color-wrapper .theme-dark::before {
    content: "DARK";
    margin-right: var(--size-2-3);
}